.wf-detail{--wf-accent:var(--wf-color-primary,#12b8a6);--wf-panel:var(--wf-color-surface,#fff);--wf-border:var(--wf-color-border,#dbe4ea);--wf-text:var(--wf-color-text,#102230);--wf-muted:var(--wf-color-muted,#647482);box-sizing:border-box;max-width:1100px;margin:0 auto;padding:clamp(1rem,3vw,2.5rem);color:var(--wf-text);font-family:Inter,system-ui,sans-serif}.wf-detail *{box-sizing:border-box}.wf-detail__back{display:inline-flex;margin:.25rem 0 1rem;color:var(--wf-accent);font-weight:750;text-decoration:none}.wf-detail__status{margin:0 0 1rem;color:var(--wf-muted)}.wf-detail__status[data-error=true]{padding:.75rem;border-radius:.65rem;background:#fff2f2;color:#a12626}.wf-detail__layout{display:grid;grid-template-columns:minmax(16rem,1.1fr) minmax(16rem,.9fr);gap:1.5rem}.wf-detail__gallery{display:grid;gap:.75rem;align-content:start}.wf-detail__image{width:100%;aspect-ratio:4/3;object-fit:contain;background:var(--wf-color-secondary,#f1f4f6);border:1px solid var(--wf-border);border-radius:1rem}.wf-detail__thumbs{display:flex;flex-wrap:wrap;gap:.5rem}.wf-detail__thumb{width:4.5rem;height:4.5rem;padding:.2rem;border:1px solid var(--wf-border);border-radius:.7rem;background:var(--wf-panel);cursor:pointer}.wf-detail__thumb[aria-current=true]{border-color:var(--wf-accent);box-shadow:0 0 0 2px var(--wf-border)}.wf-detail__thumb img{width:100%;height:100%;object-fit:contain}.wf-detail__meta{margin:0 0 .35rem;color:var(--wf-muted);font-size:.77rem;letter-spacing:.05em;text-transform:uppercase}.wf-detail h1{margin:0;font-size:clamp(1.6rem,3vw,2.4rem);line-height:1.15}.wf-detail__price{margin:.8rem 0 0;font-size:1.35rem;font-weight:850}.wf-detail__stock{margin:.35rem 0 0;color:#197149;font-size:.9rem}.wf-detail__stock[data-empty=true]{color:#a63d3d}.wf-detail__description{margin-top:1rem;line-height:1.55;white-space:pre-wrap}.wf-detail__specs{margin-top:2rem}.wf-detail__specs h2{margin:0 0 .75rem;font-size:1.15rem}.wf-detail table{width:100%;border-collapse:collapse}.wf-detail th,.wf-detail td{padding:.7rem .2rem;border-bottom:1px solid var(--wf-border);text-align:left;vertical-align:top}.wf-detail th{width:38%;color:var(--wf-muted);font-weight:650}.wf-detail__link{color:inherit;font-weight:700;text-decoration:none}.wf-detail__link:hover{color:var(--wf-accent)}.wf-detail__related{margin-top:2.5rem}.wf-detail__related h2{margin:0 0 .75rem;font-size:1.15rem}.wf-detail__related-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:.75rem}.wf-detail__card{display:flex;flex-direction:column;gap:.45rem;padding:.7rem;border:1px solid var(--wf-border);border-radius:1rem;background:var(--wf-panel);color:inherit;text-decoration:none}.wf-detail__card img{width:100%;aspect-ratio:4/3;object-fit:contain;background:var(--wf-color-secondary,#f1f4f6);border-radius:.7rem}.wf-detail__card-body{display:flex;flex-direction:column;gap:.2rem}.wf-detail__card-brand{color:var(--wf-muted);font-size:.72rem;letter-spacing:.04em;text-transform:uppercase}.wf-detail__card strong{font-size:.95rem;line-height:1.3}@media(max-width:800px){.wf-detail__layout{grid-template-columns:1fr}.wf-detail__related-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}
