.wf-shop{max-width:1160px;padding:32px 24px 64px;margin:0 auto;min-height:45vh}
.wf-shop h1{font-size:clamp(26px,4vw,36px);line-height:1.15;margin:0 0 24px;font-weight:800;letter-spacing:-.025em}
