.wf-shop-btn,.wf-shop-heart,.wf-shop-link{font:inherit;cursor:pointer;min-height:42px;border-radius:8px;transition:background-color .15s}
.wf-shop-btn{display:inline-flex;align-items:center;justify-content:center;padding:10px 17px;font-weight:750;text-decoration:none;background:var(--shop-accent);border:1px solid transparent;color:var(--wf-shop-on-accent,#171a1c);line-height:1.3}
.wf-shop-btn:hover{filter:brightness(.96)}.wf-shop-btn:disabled{background:#edf0f2;color:#778189;cursor:default;filter:none}.wf-shop-btn:focus-visible,.wf-shop-heart:focus-visible,.wf-shop input:focus-visible,.wf-shop select:focus-visible,.wf-shop-actions input:focus-visible{outline:2px solid var(--shop-accent);outline-offset:3px}
.wf-shop-link{border:0;background:transparent;color:var(--shop-muted);padding:6px 8px;text-decoration:underline;text-underline-offset:3px;font-size:13px}
.wf-shop-shell{display:flex;align-items:center;gap:5px}.wf-shop-shell a{display:inline-flex;align-items:center;gap:6px;padding:9px;color:inherit;text-decoration:none;border-radius:8px;min-height:42px;white-space:nowrap}.wf-shop-shell a:hover{background:var(--wf-color-secondary,#f4f5f6)}
.wf-shop-shell svg,.wf-shop-heart svg{width:21px;height:21px;flex:none}.wf-shop-shell [data-wf-cart-count]{font-size:11px;line-height:18px;min-width:18px;text-align:center;background:var(--shop-text);color:var(--shop-surface);border-radius:9px;font-variant-numeric:tabular-nums}
.wf-shop-actions{padding:10px 12px 12px;border-top:1px solid var(--shop-border);min-height:65px}.wf-detail [data-wf-shop-actions]{padding:16px 0;margin-top:12px}.wf-shop-actions__row{display:flex;align-items:center;gap:6px;flex-wrap:wrap}.wf-shop-actions .wf-shop-btn{flex:1;font-size:13px;padding:9px 10px;min-width:115px}.wf-shop-qty{width:62px;min-width:0;min-height:42px;border:1px solid var(--shop-border);border-radius:8px;background:var(--shop-surface);color:var(--shop-text);font:inherit;padding:8px 5px;text-align:center;font-variant-numeric:tabular-nums}.wf-shop-unit{font-size:12px;color:var(--shop-muted)}
.wf-shop-actions[data-wf-variants=true]{min-height:115px}.wf-product:has(.wf-shop-actions)>.wf-product__link{height:auto;flex:1}
.wf-product:has(.wf-shop-actions){position:relative}.wf-product .wf-shop-heart{position:absolute;top:10px;right:10px;z-index:2;box-shadow:0 1px 4px #0001}.wf-catalog[data-badge-position=top-end] .wf-product .wf-shop-heart{left:10px;right:auto}.wf-shop-actions .wf-shop-qty{width:56px}.wf-product .wf-shop-btn{min-width:105px;font-size:12px}.wf-shop-unit{white-space:nowrap}
.wf-shop-heart{display:inline-flex;align-items:center;justify-content:center;flex:none;width:42px;border:1px solid var(--shop-border);background:var(--shop-surface);color:var(--shop-muted)}.wf-shop-heart[aria-pressed=true]{color:#b52737;background:#fff5f6}.wf-shop-heart[aria-pressed=true] svg{fill:currentColor}
.wf-shop-variant{width:100%;margin-bottom:8px;padding:10px;border:1px solid var(--shop-border);border-radius:8px;font:inherit;background:var(--shop-surface);color:var(--shop-text)}
.wf-shop-lines{border-top:1px solid var(--shop-border);margin-bottom:24px}.wf-shop-line{display:flex;align-items:center;gap:18px;padding:20px 0;border-bottom:1px solid var(--shop-border);min-width:0}.wf-shop-line img{width:88px;height:88px;object-fit:cover;border-radius:10px;background:#f5f6f7}.wf-shop-line__body{display:flex;flex:1;flex-direction:column;gap:7px;min-width:0}.wf-shop-line a{color:var(--shop-text);font-weight:750;text-decoration:none}.wf-shop-line a:hover{text-decoration:underline}.wf-shop-line small{color:var(--shop-muted);font-size:12px}.wf-shop-line__controls{display:flex;align-items:center;gap:8px;flex-wrap:wrap;justify-content:flex-end}.wf-shop-line__controls strong{display:block;min-width:100px;text-align:right;font-variant-numeric:tabular-nums}.wf-shop-line__controls .wf-shop-qty{width:78px}
.wf-shop-totals{width:min(100%,370px);margin-left:auto;border-top:1px solid var(--shop-border);padding-top:12px}.wf-shop-totals>div{display:flex;justify-content:space-between;gap:20px;padding:7px 0;font-variant-numeric:tabular-nums}.wf-shop-totals>div:last-child{font-size:21px;font-weight:800;padding-top:16px;border-top:1px solid var(--shop-border);margin-top:6px}.wf-shop-help{font-size:13px;color:var(--shop-muted);line-height:1.5}.wf-shop-empty{padding:32px 0;color:var(--shop-muted)}
.wf-shop-form{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px;max-width:800px}.wf-shop-field{display:flex;flex-direction:column;gap:7px;font-size:13px;color:var(--shop-muted)}.wf-shop-field input,.wf-shop-field select,.wf-shop-field textarea{width:100%;min-height:44px;border:1px solid var(--shop-border);border-radius:8px;background:var(--shop-surface);color:var(--shop-text);font:inherit;font-size:15px;padding:10px 12px}.wf-shop-field:has(textarea),.wf-shop-form>.wf-shop-btn,.wf-shop-form>.wf-shop-error{grid-column:1/-1}.wf-shop-field textarea{min-height:96px;resize:vertical}.wf-shop-address{grid-column:1/-1;display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}.wf-shop-form>.wf-shop-btn{justify-self:start}.wf-shop-error{color:#a12626;font-size:14px;margin:0}.wf-shop-error:empty{display:none}.wf-shop-preview{background:#fff8ea;border:1px solid #f0d49e;color:#694711;padding:12px 16px;border-radius:8px;font-size:14px;line-height:1.5}.wf-shop-review{max-width:900px}.wf-shop-notice{position:fixed;z-index:10000;bottom:24px;left:50%;transform:translateX(-50%);max-width:calc(100% - 32px);background:#23312a;color:#fff;border-radius:10px;padding:13px 20px;box-shadow:0 4px 20px #0002;font:14px/1.5 system-ui}.wf-shop-notice:empty{display:none}.wf-shop-notice[data-error=true]{background:#852e2e}
@media(max-width:700px){.wf-shop{padding:24px 16px 48px}.wf-shop-line{gap:12px;flex-wrap:wrap}.wf-shop-line img{width:65px;height:65px}.wf-shop-line__controls{width:100%;justify-content:flex-start;padding-left:77px}.wf-shop-line__controls strong{margin-left:auto}.wf-shop-form,.wf-shop-address{grid-template-columns:1fr}.wf-shop-form>.wf-shop-btn{width:100%}.wf-shop-shell a{padding:7px}.wf-shop-shell [data-wf-cart-label]{display:none}.wf-shop-actions{padding:10px}.wf-shop-actions .wf-shop-btn{min-width:120px}.wf-shop-notice{bottom:16px;width:max-content}}
@media(prefers-reduced-motion:reduce){.wf-shop-btn,.wf-shop-heart,.wf-shop-link{transition:none}}

